        @Expose
        @ConfigOption(name = "Хаб (Hub)", desc = "Музыка для центрального хаба.")
        @Accordion
        var hub = LocationMusicEntryConfig()

        @Expose
        @ConfigOption(name = "Остров игрока (Private Island)", desc = "Музыка для личного острова.")
        @Accordion
        var privateIsland = LocationMusicEntryConfig()

        @Expose
        @ConfigOption(name = "Парк (The Park)", desc = "Музыка для локации Парк.")
        @Accordion
        var thePark = LocationMusicEntryConfig()

        @Expose
        @ConfigOption(name = "Спайдерская берлога (Spider's Den)", desc = "Музыка для Спайдерской берлоги.")
        @Accordion
        var spidersDen = LocationMusicEntryConfig()

        @Expose
        @ConfigOption(name = "Край Пустоты (The End)", desc = "Музыка для Края Пустоты.")
        @Accordion
        var theEnd = LocationMusicEntryConfig()

        @Expose
        @ConfigOption(name = "Багровые острова (Crimson Isle)", desc = "Музыка для Багровых островов.")
        @Accordion
        var crimsonIsle = LocationMusicEntryConfig()

        @Expose
        @ConfigOption(name = "Глубинное убежище (Deep Caverns)", desc = "Музыка для Глубинного убежища.")
        @Accordion
        var deepCaverns = LocationMusicEntryConfig()

        @Expose
        @ConfigOption(name = "Шахты (Gold Mine / Coal Mine)", desc = "Музыка для начальных шахт.")
        @Accordion
        var mines = LocationMusicEntryConfig()

        @Expose
        @ConfigOption(name = "Деревня (Village)", desc = "Музыка для деревни.")
        @Accordion
        var village = LocationMusicEntryConfig()

        @Expose
        @ConfigOption(name = "Подземелья (Dungeons)", desc = "Музыка для подземелий.")
        @Accordion
        var dungeons = LocationMusicEntryConfig()

        class LocationMusicEntryConfig {
            @Expose
            @ConfigOption(name = "Включить для этой локации", desc = "Воспроизводить музыку в этой локации.")
            @ConfigEditorBoolean
            var enabled = true

            @Expose
            @ConfigOption(name = "Путь к файлу", desc = "Путь к аудиофайлу относительно assets/mods/starredheltix/sounds/")
            var soundPath = ""
        }
    }
}

