        var particleScale = 1.2f

        @Expose
        @ConfigOption(name = "Количество частиц", desc = "Максимальное количество нот на экране.")
        @ConfigEditorSlider(minValue = 5f, maxValue = 50f, minStep = 1f)
        var maxParticles = 25f

        @Expose
        @ConfigOption(name = "🔴 Боевые локации", desc = "Адская крепость, Кладбище, Логово Арахны, Руины и др.")
