package set.starlev.features.music

/**
 * Категории локаций для визуальной музыки.
 * Каждая категория содержит список локаций и настройки мелодии.
 */
enum class LocationMusicCategory(
    val displayName: String,
    val emoji: String,
    val locations: Set<String>,
    val baseNotes: List<Int>,       // MIDI-ноты базовой мелодии (расширенные)
    val harmonyNotes: List<Int>,    // MIDI-ноты гармонии (расширенные)
    val rhythmPattern: List<Int>,   // Паттерн ритма (в тиках, удлинённый)
    val atmosphere: AtmosphereType
) {
    COMBAT(
        displayName = "Боевые локации",
        emoji = "🔴",
        locations = setOf(
            "адская крепость", "лагерь археолога", "кладбище",
            "логово арахны", "паучье логово", "убежище арахны",
            "руины"
        ),
        // Расширенная минорная мелодия — 16 нот для длинных треков
        baseNotes = listOf(
            48, 51, 53, 55, 58, 60, 63, 65,
            67, 65, 63, 60, 58, 55, 53, 51
        ),
        harmonyNotes = listOf(
            36, 39, 41, 43, 46, 48, 51, 53,
            55, 53, 51, 48, 46, 43, 41, 39
        ),
        // Удлинённый ритм-паттерн — 16 шагов
        rhythmPattern = listOf(4, 2, 4, 2, 3, 2, 4, 1, 4, 2, 3, 2, 4, 2, 3, 1),
        atmosphere = AtmosphereType.INTENSE
    ),

    FARMING(
        displayName = "Фермерские локации",
        emoji = "🟡",
        locations = setOf(
            "амбар", "грибная пустыня", "оазис", "ферма"
        ),
        // Расширенная мажорная мелодия — 16 нот
        baseNotes = listOf(
            60, 62, 64, 65, 67, 69, 71, 72,
            74, 72, 69, 67, 65, 64, 62, 60
        ),
        harmonyNotes = listOf(
            48, 50, 52, 53, 55, 57, 59, 60,
            62, 60, 57, 55, 53, 52, 50, 48
        ),
        rhythmPattern = listOf(6, 4, 6, 4, 6, 4, 8, 4, 6, 4, 6, 4, 8, 4, 6, 4),
        atmosphere = AtmosphereType.CALM
    ),

    FORAGING(
        displayName = "Леснические локации",
        emoji = "🟢",
        locations = setOf(
            "дом викингов", "лес", "берёзовый парк", "джунгли",
            "дикая природа", "еловый лес", "саванна", "тёмная чаща"
        ),
        // Расширенная пентатоника — 16 нот
        baseNotes = listOf(
            57, 59, 60, 62, 64, 65, 67, 69,
            71, 69, 67, 65, 64, 62, 60, 59
        ),
        harmonyNotes = listOf(
            45, 47, 48, 50, 52, 53, 55, 57,
            59, 57, 55, 53, 52, 50, 48, 47
        ),
        rhythmPattern = listOf(5, 3, 5, 3, 6, 4, 5, 3, 5, 3, 6, 4, 5, 3, 6, 3),
        atmosphere = AtmosphereType.NATURE
    ),

    MINING(
        displayName = "Шахтёрские локации",
        emoji = "🔵",
        locations = setOf(
            "королевский дворец", "лавовый источник", "норы гоблинов",
            "борота дивана", "гномья кузница", "золотая шахта",
            "гравиевые шахты", "алмазный резерв", "божущая пещера",
            "великая ледяная стена", "верхние шахты", "глубокие пещеры",
            "дальний резерв", "горные рудники", "карьер", "королевские шахты",
            "кузница", "лазуритовый карьер", "пороховые пещеры",
            "слизневая гора", "угольная шахта", "обсидиановое святилище",
            "логово свинозомби"
        ),
        // Расширенная глубокая мелодия — 16 нот
        baseNotes = listOf(
            45, 47, 48, 50, 52, 53, 55, 57,
            60, 57, 55, 53, 52, 50, 48, 47
        ),
        harmonyNotes = listOf(
            33, 35, 36, 38, 40, 41, 43, 45,
            48, 45, 43, 41, 40, 38, 36, 35
        ),
        rhythmPattern = listOf(3, 2, 3, 2, 4, 2, 3, 1, 3, 2, 4, 2, 3, 2, 4, 1),
        atmosphere = AtmosphereType.DEEP
    ),

    ENDER(
        displayName = "Эндер локации",
        emoji = "🟣",
        locations = setOf(
            "драконье гнездо", "пустотный склеп", "энд",
            "убежище зеалотов"
        ),
        // Расширенная мистическая мелодия — 16 нот
        baseNotes = listOf(
            40, 43, 45, 48, 51, 53, 55, 58,
            60, 58, 55, 53, 51, 48, 45, 43
        ),
        harmonyNotes = listOf(
            28, 31, 33, 36, 39, 41, 43, 46,
            48, 46, 43, 41, 39, 36, 33, 31
