        rhythmPattern = listOf(8, 4, 6, 3, 8, 4, 10, 5, 8, 4, 6, 3, 8, 4, 10, 5),
        atmosphere = AtmosphereType.MYSTIC
    ),

    MYSTERIOUS(
        displayName = "Загадочные локации",
        emoji = "⚪️",
        locations = setOf(
            "бездна", "гора", "туман"
        ),
        // Расширенная эмбиент мелодия — 16 нот
