        atmosphere = AtmosphereType.ETHEREAL
    ),

    HUB(
        displayName = "Хаб локации",
        emoji = "⚫️",
        locations = setOf(
            "библиотека", "общественный центр", "магазин модной одежды",
            "оружейная", "музей", "таверна", "дом строителя",
            "рыночный переулок", "аукцион", "банк"
        ),
        // Расширенная социальная мелодия — 16 нот
        baseNotes = listOf(
            60, 62, 64, 67, 69, 72, 74, 76,
            77, 76, 74, 72, 69, 67, 64, 62
        ),
        harmonyNotes = listOf(
            48, 50, 52, 55, 57, 60, 62, 64,
            65, 64, 62, 60, 57, 55, 52, 50
        ),
        rhythmPattern = listOf(6, 4, 6, 4, 6, 4, 8, 4, 6, 4, 6, 4, 8, 4, 6, 4),
        atmosphere = AtmosphereType.SOCIAL
    );

    companion object {
        /**
         * Определить категорию по названию локации.
         * Ищет строку scoreboard, содержащую название локации.
         */
        fun fromLocation(locationName: String): LocationMusicCategory? {
            val clean = locationName.lowercase().trim()
            for (category in entries) {
                for (loc in category.locations) {
                    // Проверяем: строка scoreboard содержит название локации
                    if (clean.contains(loc.lowercase())) {
                        return category
                    }
                }
            }
            return null
        }
    }
}

/**
 * Тип атмосферы для визуальных эффектов.
 */
enum class AtmosphereType {
    INTENSE,    // Боевая - резкие частицы, красные вспышки
    CALM,       // Фермерская - плавные, тёплые тона
    NATURE,     // Лесная - зелёные, органические формы
    DEEP,       // Шахтёрская - тяжёлые, медленные частицы
    MYSTIC,     // Эндер - фиолетовые, телепортирующие
    ETHEREAL,   // Загадочная - полупрозрачные, парящие
    SOCIAL      // Хаб - нейтральные, упорядоченные
}

