package set.starlev.features.music

/**
 * Категории локаций для визуальной музыки.
 * Каждая категория содержит несколько секций мелодии для длинных looped треков (2-3 мин).
 */
enum class LocationMusicCategory(
    val displayName: String,
    val emoji: String,
    val locations: Set<String>,
    val sections: List<Section>,     // Секции мелодии (чередуются)
    val rhythmPatterns: List<List<Int>>, // Разные ритм-паттерны для вариативности
    val atmosphere: AtmosphereType
) {
    COMBAT(
        displayName = "Боевые локации",
        emoji = "🔴",
        locations = setOf(
            "адская крепость", "лагерь археолога", "кладбище",
            "логово арахны", "паучье логово", "убежище арахны",
            "руины"
        ),
        sections = listOf(
            // Секция A — напряжённое нарастание
            Section(
                baseNotes = listOf(
                    48, 51, 53, 55, 58, 60, 63, 65,
                    67, 65, 63, 60, 58, 55, 53, 51,
                    48, 53, 58, 63, 67, 65, 60, 55
                ),
                harmonyNotes = listOf(
                    36, 39, 41, 43, 46, 48, 51, 53,
                    55, 53, 51, 48, 46, 43, 41, 39,
                    36, 41, 46, 51, 55, 53, 48, 43
                )
            ),
            // Секция B — агрессивный пик
            Section(
                baseNotes = listOf(
                    60, 63, 65, 67, 70, 72, 70, 67,
                    65, 63, 60, 58, 55, 58, 60, 63,
                    65, 67, 70, 72, 75, 72, 70, 67
                ),
                harmonyNotes = listOf(
                    48, 51, 53, 55, 58, 60, 58, 55,
                    53, 51, 48, 46, 43, 46, 48, 51,
                    53, 55, 58, 60, 63, 60, 58, 55
                )
            ),
            // Секция C — затишье перед бурей
            Section(
                baseNotes = listOf(
                    55, 53, 51, 48, 46, 48, 51, 53,
                    55, 58, 60, 63, 60, 58, 55, 53,
                    51, 48, 46, 43, 46, 48, 51, 53
                ),
                harmonyNotes = listOf(
                    43, 41, 39, 36, 34, 36, 39, 41,
                    43, 46, 48, 51, 48, 46, 43, 41,
                    39, 36, 34, 31, 34, 36, 39, 41
                )
